grammar audit.NextInlineOptionalFollow hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal VALUE: 'a'? 'ab';

grammar audit.NextInlineStarFollow hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal VALUE: 'a'* 'ab';

grammar audit.NextInlinePlusFollow hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal VALUE: 'a'+ 'ab';

grammar audit.NextGroupedStarFollow hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal VALUE: ('ab')* 'ac';

grammar audit.NextFragmentStarFollow hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal VALUE: BODY 'ab';
terminal fragment BODY: 'a'*;

grammar audit.NextChoiceStarFollow hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal VALUE: ('a'|'ab')* 'ac';

grammar audit.NextInlineUntilRepeat hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal VALUE: ('@' ->'ab')+ 'c';

grammar audit.NextFragmentUntilRepeat hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal VALUE: BLOCK+ 'c';
terminal fragment BLOCK: '@' ->'ab';
